import numpy as np
from sklearn.feature_extraction.text import TfidfVectorizer
import re

def task_func(example_str):
    outside_parts = []
    depth = 0

    for char in example_str:
        if char == '[':
            depth += 1
        elif char == ']':
            if depth > 0:
                depth -= 1
            elif depth == 0:
                outside_parts.append(char)
        elif depth == 0:
            outside_parts.append(char)

    text_outside = ''.join(outside_parts).strip()
    if not text_outside:
        return {}

    vectorizer = TfidfVectorizer(token_pattern=r'(?u)\b\w+\b')

    try:
        tfidf_matrix = vectorizer.fit_transform([text_outside])
    except ValueError:
        return {}

    feature_names = vectorizer.get_feature_names_out()
    scores = tfidf_matrix.toarray()[0]

    return {word: float(score) for word, score in zip(feature_names, scores)}
